// === Tab: Tile ===
class Tile {
  constructor(pos, dim, txt, tnt = null) {
    this.pos = pos;
    this.dim = dim;
    this.txt = txt;
		if (dim.x === dim.y) {
			// get square texture by cropping 
			const ts = min(txt.width, txt.height);
			this.txt = txt.get(~~random(txt.width-ts), ~~random(txt.height-ts), ts, ts);
		}
    this.tnt = tnt; // tint
    // console.log(this);
  }

  show() {
    push();
    texture(this.txt);

    noStroke();

    if (this.tnt) tint(this.tnt); // tint black tiles

    translate(this.pos.x, this.pos.y, this.pos.z);
    box(this.dim.x, this.dim.y, this.dim.z);
    pop();
  }
}

