class Figure {
	constructor(typ, pos, sze, col, isWhite = true) {
		this.typ = typ;
		this.pos = pos;
		this.dst = {pos: null, frames: 60, current: 0, easing: null};
		this.sze = sze;
		this.col = col;
		this.isw = isWhite;
		this.createModell();
	}

	moveTo(dst, frames) {
		if (this.dst && this.dst.pos === null) {
			this.dst = {pos: dst, frames, current: 0, easing: random(easingFuncs)};
			const chessFigures = ["♙", "♖", "♘", "♗", "♕", "♔", "♟︎", "♜", "♞", "♝", "♛", "♚"];
			const cFidx = this.typ + (this.isw ? 0 : 6) - 1; // chess figure index
			console.log(chessFigures[cFidx] + " " + String.fromCharCode(97 + this.pos.x) + (this.pos.y+1) + " " + String.fromCharCode(97 + dst.x) + (dst.y+1))
		}
	}

	show() {
		let pos = this.pos;
		if (this.dst && this.dst.pos) {
			const f = constrain(this.dst.easing(this.dst.current / this.dst.frames), 0, 1);
			pos.x = lerp(pos.x, this.dst.pos.x, f);
			pos.y = lerp(pos.y, this.dst.pos.y, f);
			this.dst.current++;
			// move finished
			if (this.dst.current > this.dst.frames) {
				this.dst = {pos: null, frames: 60, current: 0};
			}
		}
		push();
		translate((pos.x - 4) * this.sze + this.sze / 2, -(pos.y - 3) * this.sze + this.sze / 2, pos.z);
		noStroke(); // must be explicitly set, even when in model already
		model(this.shape);
		pop();
	}

	createModell() {
		let pos = this.pos;
		if (this.dst && this.dst.pos) {
			const f = constrain(this.dst.easing(this.dst.current / this.dst.frames), 0, 1);
			pos.x = lerp(pos.x, this.dst.pos.x, f);
			pos.y = lerp(pos.y, this.dst.pos.y, f);
			this.dst.current++;
			// move finished
			if (this.dst.current > this.dst.frames) {
				this.dst = {pos: null, frames: 60, current: 0};
			}
		}
		beginGeometry();
		// translate((pos.x - 4) * this.sze + this.sze / 2, -(pos.y - 3) * this.sze + this.sze / 2, pos.z); 

		noStroke(); // not working here, must be set in show() call each time
		fill(this.col);

		switch (this.typ) {
			case 1: // pawn / Bauer
				{
					const sze = this.sze * 0.35
					translate(0, 0, sze);
					sphere(sze);
				}
				break;

			case 2: // Rook / turm
				{
					const f1 = 1.3
					const f2 = 1.5
					const szeW = this.sze * 0.35
					const szeH = this.sze * 0.6
					box(szeW * f1, szeW * f1, szeH / 4);
					translate(0, 0, szeH / 2);
					box(szeW, szeW, szeH);

					translate(0, 0, szeH / 2 + szeH / 8);
					box(szeW * f2, szeW * f2, szeH / 4);

					// 4 corners on top
					translate(szeW*f2/2 - szeH/8, szeW*f2/2 - szeH/8, szeH/4); // 
					box(szeH/4)
					translate(-szeW*f2 + szeH/4, 0, 0);
					box(szeH/4)
					translate(0, -szeW*f2 + szeH/4, 0);
					box(szeH/4)
					translate(szeW*f2 - szeH/4 , 0, 0);
					box(szeH/4)
				}
				break;

			case 3: // kNight / Pferd
				{
					const szeW = this.sze * 0.4;
					const szeH = this.sze * 1.0;
					translate(0, 0, szeH / 2);
					box(szeW * 0.5, szeW * 1.2, szeH * 0.95)
					rotateX(HALF_PI)
					cone(szeW, szeH);
				}
				break;

			case 4: // 	Bishop / Läufer
				{
					const szeW = this.sze * 0.4;
					const szeH = this.sze * 1.0;
					translate(0, 0, szeH / 2);
					rotateX(HALF_PI)
					scale(0.8, 1, 1)
					cone(szeW, szeH, 5);
				}
				break;

			case 5: // Queen / Königin
				{
					const szeW = this.sze * 0.3;
					const szeH = this.sze * 1.0;
					translate(0, 0, szeH / 2);
					rotateX(HALF_PI)
					cone(szeW, szeH);
					cylinder(szeW / 2, szeH);
					rotateX(-HALF_PI)
					translate(0, 0, szeH/2)
					sphere(szeW*3/4)
				}
				break;

			case 6: // King / König
				{
					const szeW = this.sze * 0.3;
					const szeH = this.sze * 1.0;
					translate(0, 0, szeH / 2);
					rotateX(HALF_PI)
					cylinder(szeW, szeH);
					rotateX(-HALF_PI)
					translate(0, 0, szeH/2 + (szeW*3/4))
					sphere(szeW*3/4)
				}
				break;

		}

		this.shape = endGeometry();
	}

	entropy(x, y, usedSpots) {
		const location = `x${x}y${y}`;
		const isEmpty = usedSpots.find((element) => element === location) === undefined;
		// console.log(`${this.typ}, ${this.isw}, ${location}, ${isEmpty}`)
		if (isEmpty && !(x < 0 || y < 0 || x > 7 || y > 7) ) {			
			this.entropies.push({x, y});
			return true;
		}
		return false;
	}
	getEntropies(usedSpots) {
		this.entropies = [];

		switch (this.typ) {
			case 1: // pawn / Bauer
				{
					//
					const dir = this.isw ? 1 : -1;
					const x = this.pos.x; 
					let y = this.pos.y + dir;
					if (this.entropy(x, y, usedSpots) && ((this.isw && y === 2) || (!this.isw && y === 5))) {
						y += dir;
						this.entropy(x, y, usedSpots);
					}
				}
				break;

			case 2: // Rook / turm
				{
					let x, y;
					// horiz
					y = this.pos.y;
					for (x = this.pos.x+1; x < 8; x++) {
						if (!this.entropy(x, y, usedSpots)) break;
					}
					for (x = this.pos.x-1; x >= 0; x--) {
						if (!this.entropy(x, y, usedSpots)) break;
					}
					// vert
					x = this.pos.x;
					for (y = this.pos.y+1; y < 8; y++) {
						if (!this.entropy(x, y, usedSpots)) break;
					}
					for (y = this.pos.y-1; y >= 0; y--) {
						if (!this.entropy(x, y, usedSpots)) break;
					}
				}
				break;

			case 3: // kNight / Pferd
				{
					//
					const x = this.pos.x;
					const y = this.pos.y;
					this.entropy(x+1, y+2, usedSpots);
					this.entropy(x+2, y+1, usedSpots);
					this.entropy(x+2, y-1, usedSpots);
					this.entropy(x+1, y-2, usedSpots);
					this.entropy(x-1, y+2, usedSpots);
					this.entropy(x-2, y+1, usedSpots);
					this.entropy(x-2, y-1, usedSpots);
					this.entropy(x-1, y-2, usedSpots);
				}
				break;

			case 4: // 	Bishop / Läufer
				{
					// diagonal
					for (let dy = -1; dy <= 1; dy += 2) {
						for (let dx = -1; dx <= 1; dx += 2) {
							let x = this.pos.x;
							let y = this.pos.y;
							let _wG_1 = 0; while ((x >= 0 && y >= 0 && x < 8 && y < 8) && ++_wG_1 < 20000) {
								x += dx;
								y += dy;
								if (!this.entropy(x, y, usedSpots)) break;
							} // follow path
						}	// dx
					} // dy

				}
				break;

			case 5: // Queen / Königin
				{
					// like rook
					let x, y;
					// horiz
					y = this.pos.y;
					for (x = this.pos.x+1; x < 8; x++) {
						if (!this.entropy(x, y, usedSpots)) break;
					}
					for (x = this.pos.x-1; x >= 0; x--) {
						if (!this.entropy(x, y, usedSpots)) break;
					}
					// vert
					x = this.pos.x;
					for (y = this.pos.y+1; y < 8; y++) {
						if (!this.entropy(x, y, usedSpots)) break;
					}
					for (y = this.pos.y-1; y >= 0; y--) {
						if (!this.entropy(x, y, usedSpots)) break;
					}

					// diagonal
					for (let dy = -1; dy <= 1; dy += 2) {
						for (let dx = -1; dx <= 1; dx += 2) {
							let x = this.pos.x;
							let y = this.pos.y;
							let _wG_2 = 0; while ((x >= 0 && y >= 0 && x < 8 && y < 8) && ++_wG_2 < 20000) {
								x += dx;
								y += dy;
								if (!this.entropy(x, y, usedSpots)) break;
							} // follow path
						}	// dx
					} // dy
				}
				break;

			case 6: // King / König
				{
					// 
					for (let y = this.pos.y-1; y <= this.pos.y+1; y++) {
						for (let x = this.pos.x-1; x <= this.pos.x+1; x++) {						
							this.entropy(x, y, usedSpots);
						}						
					}
				}
				break;

		} // switch typ
	} // entropy(usedSpots)
} // class Figure

