let
  woodTxt, // big texture
  tiles = [],  // all 8x8 b&w tiles
	frames = [], // frames around the 8x8 tiles
	figures = [], // all 32 figures
	nextMoveWhite = true;

function preload() {
  woodTxt = loadImage(
    "file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png"
  );
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
	describe("chessboard consisting of tinted wood textures and simple 3d figures");
	camera(0, 1500, 1500);
  frameRate(60);
	createScene();
}

function draw() {
	if (frameCount % 10 === 0) boardMoveFigures();

  background(0, 0, 8);

	lights();
	// ambientLight("white");

  orbitControl();

	// tiles
  for (let t of tiles) {
    t.show();
  }

	// frames
  for (let t of frames) {
    t.show();
  }

	// figures
  for (let f of figures) {
    f.show();
  }
}

function boardMoveFigures() {
	// get used spots
	const usedSpots = [];
	for (let f of figures) {
    usedSpots.push(`x${f.pos.x}y${f.pos.y}`)
		if (f.dst && f.dst.pos !== null) {		
			usedSpots.push(`x${f.dst.pos.x}y${f.dst.pos.y}`)
		}
  }

	// get entropy for each figure
	for (let f of figures) {
		f.getEntropies(usedSpots);
	}
	// console.log(figures)

	boardMoveFiguresRules();
	// boardMoveFiguresRandom(usedSpots)
}


function boardMoveFiguresRules() {
	let success = false;
	let tries = 100;

	let _wG_3 = 0; while ((!success && tries--) && ++_wG_3 < 20000) {		
		const fig = random(figures);
		if (fig.isw === nextMoveWhite && fig.entropies && fig.entropies.length > 0) {
			const entropy = random(fig.entropies);
			fig.moveTo({x: entropy.x, y: entropy.y}, 60);
			success = true;
			nextMoveWhite = !nextMoveWhite
		}
	}

}


function boardMoveFiguresRandom(usedSpots) {
	// get random free spot
	let freeSpot = null, x, y;
	let _wG_4 = 0; while ((freeSpot === null) && ++_wG_4 < 20000) {
		x = ~~random(CTN);
		y = ~~random(CTN);
		const location = `x${x}y${y}`;
		const found = usedSpots.find((element) => element == location);
		if (found === undefined) {
			freeSpot = location;
		}
	}

	// move random figure to random free spot
	const fig = random(figures);
	fig.moveTo({x, y}, 60);
}


