			txts.push(woodTxt.get(x, y, tw, th));
    }
  }
  // console.log(txts);

	let zOff = ts / 5;

	// tiles
  for (let yi = -4; yi < 4; yi++) {
    for (let xi = -4; xi < 4; xi++) {
      const x = xi * ts + ts / 2; // ~~random(width / ts) * ts;
