        // random() < 0.5
        tnt = TINT_BROWN;
				// tnt = random(["rgb(69,10,10)", "rgb(7,7,62)", "rgb(6,54,6)"])
      } else {
        tnt = "";
      }
      tiles.push(new Tile({x, y, z: 0}, {x: ts, y: ts, z: zOff}, random(txts), tnt));
    }
  }

	// frames
	const frW1 = ts / 10; // frame width 1st frame
	const frW2 = ts / 3; // frame width 2nd frame
	const frT1 = random(txts);
	const frT2 = random(txts);
	frames.push(new Tile({x: -4*ts-frW1/2, y: 0, z: 0}, {x: frW1, y: 8*ts + 2 * frW1, z: zOff}, frT1));
	frames.push(new Tile({x: 4*ts+frW1/2, y: 0, z: 0}, {x: frW1, y: 8*ts + 2 * frW1, z: zOff}, frT1));
	frames.push(new Tile({x: 0, y: -4*ts-frW1/2, z: 0}, {x: 8*ts, y: frW1, z: zOff}, frT1));
	frames.push(new Tile({x: 0, y: 4*ts+frW1/2, z: 0}, {x: 8*ts, y: frW1, z: zOff}, frT1));
	frames.push(new Tile({x: -4*ts-frW1-frW2/2, y: 0, z: 0}, {x: frW2, y: 8*ts + 2*frW1, z: zOff}, frT2, TINT_BROWN));
	frames.push(new Tile({x: 4*ts+frW1+frW2/2, y: 0, z: 0}, {x: frW2, y: 8*ts + 2*frW1, z: zOff}, frT2, TINT_BROWN));
	frames.push(new Tile({x: 0, y: -4*ts-frW1-frW2/2, z: 0}, {x: 8*ts + 2*frW1 + 2*frW2, y: frW2, z: zOff}, frT2, TINT_BROWN));
	frames.push(new Tile({x: 0, y: 4*ts+frW1+frW2/2, z: 0}, {x: 8*ts + 2*frW1 + 2*frW2, y: frW2, z: zOff}, frT2, TINT_BROWN));

	// figures
	zOff /= 2;
	// pawn / Bauer
	for (let i = 0; i < 8; i++) {
		figures.push(new Figure(1, {x: i, y: 1, z: zOff}, ts, CLR_WHITE))
		figures.push(new Figure(1, {x: i, y: 6, z: zOff}, ts, CLR_BLACK, false))
	}
	// Rook / turm
	figures.push(new Figure(2, {x: 0, y: 0, z: zOff}, ts, CLR_WHITE))
	figures.push(new Figure(2, {x: 7, y: 0, z: zOff}, ts, CLR_WHITE))
	figures.push(new Figure(2, {x: 0, y: 7, z: zOff}, ts, CLR_BLACK, false))
	figures.push(new Figure(2, {x: 7, y: 7, z: zOff}, ts, CLR_BLACK, false))
	// kNight / Pferd
	figures.push(new Figure(3, {x: 1, y: 0, z: zOff}, ts, CLR_WHITE))
	figures.push(new Figure(3, {x: 6, y: 0, z: zOff}, ts, CLR_WHITE))
	figures.push(new Figure(3, {x: 1, y: 7, z: zOff}, ts, CLR_BLACK, false))
	figures.push(new Figure(3, {x: 6, y: 7, z: zOff}, ts, CLR_BLACK, false))
