	figures.push(new Figure(4, {x: 5, y: 0, z: zOff}, ts, CLR_WHITE))
	figures.push(new Figure(4, {x: 2, y: 7, z: zOff}, ts, CLR_BLACK, false))
	figures.push(new Figure(4, {x: 5, y: 7, z: zOff}, ts, CLR_BLACK, false))
